with d as (select value r from jsonb_array_elements($q$[{"notes":["This pudding can be made a few hours ahead and gently reheated, or served at room temperature.","Use good-quality rose water, it should smell fragrant but not perfumy. Add it slowly and taste as you go."],"steps":[{"text":"Bring the water to a boil in a large saucepan. Add the sago slowly, stirring constantly to prevent lumps from forming. Cook, stirring often, until the sago is translucent and tender, about 12 minutes."},{"text":"Add the milk, caster sugar, cinnamon stick and crushed cardamom pods. Stir well and bring to a gentle simmer until the sugar has dissolved and the milk is fragrant."},{"text":"Cook, stirring occasionally, until the pudding thickens slightly and the sago pearls are completely soft, about 5 minutes. The mixture should be creamy but not stiff."},{"text":"Remove from the heat and stir through the rose water. Taste and add a pinch of salt to balance the sweetness. Discard the cinnamon stick."},{"text":"Divide among bowls while still warm and dust lightly with ground cinnamon. Serve warm or at room temperature."}],"id":"dd9cd41f-cc82-47b7-8176-19e73288bcb4"},{"notes":["Make the sofregit ahead: cook the onions and tomatoes up to an hour before, then reheat gently before adding the rice.","Fresh squid ink from the fishmonger can replace the sachets, ask for 2 sachets' worth (about 4 g). It will be fresher and give a rounder flavour.","Arròs negre reheats poorly, so cook it fresh and serve at once, still warm from the pan.","Food safety: Cook mussels, clams and pipis only if they are alive and tightly closed (or close when tapped), and discard any that stay shut after cooking."],"steps":[{"text":"In your rice pan or large shallow casserole over medium heat, warm the olive oil. Add the chopped onions and cook very slowly, stirring often, until completely soft and lightly golden, this is the sofregit, and it should take 12 to 15 minutes. Do not rush it; this is where the flavour lives."},{"text":"Add the tinned tomatoes to the sofregit and stir well. Cook for another 5 to 8 minutes, until the sauce thickens slightly and the raw tomato taste disappears. Season with salt and pepper."},{"text":"Stir in the garlic and chilli (if using), and cook for 1 minute until fragrant."},{"text":"Add the rice and stir constantly for 2 minutes, coating each grain with the sofregit and oil."},{"text":"Dissolve the squid ink sachets in the warm stock until the stock is jet black, then pour the stock gradually into the rice, stirring occasionally. Bring to a simmer until bubbles break across the surface."},{"text":"Cook the rice uncovered at a gentle simmer for about 15 to 18 minutes, stirring occasionally, until the rice is almost tender and the liquid has been mostly absorbed."},{"text":"Scatter the squid rings and mussels across the top of the rice. Do not stir them in. Continue cooking for 5 to 7 minutes, until the squid is just cooked through, the mussel shells have opened (discard any that don't), and the rice is tender with a slight bite. The bottom should form a thin, crispy layer (called socarrat)."},{"text":"Remove from heat, cover loosely with foil, and rest for 3 minutes. Scatter fresh parsley over the top and serve at the table in the pan."}],"id":"c16b7f17-3e03-4212-8896-9e84a51f05ae"},{"notes":["Make it a day ahead and reheat gently, the flavours deepen overnight.","If you can't find fresh palm nuts, use tinned palm cream (about 800 ml), though fresh is far superior. Skip the pounding and straining; just heat the tinned cream gently and follow from step 3.","Stockfish is essential, dried, smoked whole fish. Don't substitute with stock cubes or powder, you'll lose the soul of the soup.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"steps":[{"text":"Pound the palm nuts in a large bowl with 2 litres of hot water (not boiling), working in batches. Press through a fine sieve or colander lined with muslin cloth, squeezing gently to extract all the cream. Reserve this golden liquid and discard the fibre."},{"text":"In a large pot, bring 1 litre of water to the boil. Add the stockfish, one halved onion, and a pinch of salt. Simmer for 20 minutes, then remove the stockfish and set aside to cool. Strain the cooking liquid and reserve it (discard the onion)."},{"text":"Once the stockfish is cool enough to handle, remove the meat from the bones and break into chunks. Discard the bones."},{"text":"Pour the palm nut cream into the pot over medium heat. Stir constantly for 3–4 minutes until it thickens slightly and the oil begins to separate on top, this is how you know it's ready."},{"text":"Add the reserved stockfish cooking liquid, the stockfish meat, dried crayfish, remaining halved onion, and the scotch bonnet chillies if using. Stir well and simmer gently for 20 minutes, stirring occasionally to prevent sticking."},{"text":"Stir in the ground crayfish, salt, and black pepper. Taste and adjust seasoning. Simmer for another 10 minutes, then remove from heat. Remove the onion halves and whole chillies before serving."},{"text":"Serve hot with boiled white rice, gari, or fufu."}],"id":"5641fd55-6c6e-43a6-8c8a-ba7583956f34"},{"notes":["Make ahead: Cook the rice and prepare the chikuwa mixture up to 4 hours ahead. Reheat gently and pour over fresh rice.","Chikuwa keeps in the fridge for up to a week, so this is perfect for bento prep.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Combine dashi, soy sauce, mirin and sugar in a small saucepan or shallow pan. Bring to a simmer over medium heat until the sugar has dissolved and small bubbles appear at the edges."},{"text":"Add the sliced chikuwa and simmer for 2 minutes until heated through."},{"text":"Lightly beat the eggs in a bowl. Pour into the simmering broth in a thin stream, stirring gently until the egg is just set but still soft, about 1 minute."},{"text":"Divide the cooked rice between two bowls. Spoon the chikuwa, egg and sauce over the top. Garnish with spring onion if using, and serve hot."}],"id":"8d26edbf-621b-4f0c-90e6-fe2b8881dc33"},{"notes":["The batter can be made the night before and stored in the fridge, it actually develops better flavour overnight.","Wonton wrappers crisp up quickly, so fry them just before you start making the crepes.","A non-stick or well-seasoned crepe pan is essential. The pan must be hot enough that the batter sets instantly, or you'll struggle to spread it."],"steps":[{"text":"Mix plain flour and salt in a bowl. Slowly add water, stirring until smooth. Let the batter rest for 10 minutes."},{"text":"While the batter rests, break the wonton wrappers into rough pieces and fry in a small pan with a little oil until crispy and golden, about 2 minutes. Set aside."},{"text":"Heat a large non-stick pan or crepe pan over high heat. It should be very hot, test with a drop of water; it should sizzle and evaporate immediately."},{"text":"Pour 120 ml of batter into the centre of the pan and immediately tilt and rotate the pan so the batter spreads into a thin, even circle about 20 cm across. Work quickly."},{"text":"Let the batter cook for about 30 seconds until the bottom is set and starts to turn light golden. Crack an egg onto one half of the crepe, then use a spatula to break the yolk and spread it evenly."},{"text":"Scatter half the chopped spring onion and half the crispy wonton pieces over the egg. Fold the other half of the crepe over to enclose the filling, pressing gently."},{"text":"Cook for another 30 seconds until the egg is set, then slide onto a plate. Serve immediately with sweet chilli sauce and soy sauce for dipping."},{"text":"Repeat with the remaining batter, egg, spring onion and wonton to make a second jianbing."}],"id":"3b8e4204-f4e6-44fc-b502-605049783dbe"},{"steps":[{"text":"Heat the oil in a large pot over medium heat. Add the onion and cook, stirring, until soft and golden, about 5 minutes."},{"text":"Add the garlic and ginger, and cook for 1 minute until fragrant."},{"text":"Stir in the cumin, coriander and turmeric, and cook for 1 minute to release the spices."},{"text":"Add the eggplant chunks and stir to coat in the spice mixture. Cook for 5 minutes, stirring occasionally."},{"text":"Pour in the coconut milk and bring to a simmer until gentle bubbles appear and the sauce is slightly thickened. Add the chopped chillies and stir well."},{"text":"Reduce heat to low and simmer gently, uncovered, for 20 minutes until the eggplant is very tender. Stir occasionally."},{"text":"Taste and add salt as needed. Serve hot, scattered with fresh coriander if you like."}],"id":"95c327e5-703b-4c9b-8a2d-78ff2b2189ee"},{"notes":["Make the rice cakes up to 2 hours ahead and keep them at room temperature, covered with a damp cloth. Assemble and fold just before serving so they stay pliable.","If you can't find banana leaves, plastic wrap works fine, or serve the bánh nậm on a plate with lettuce underneath instead.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C. Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"id":"5ca24c75-c406-4c47-9990-2e57053df80e"},{"notes":["Serve warm or at room temperature with crusty bread for scooping.","Keeps in the fridge for up to 3 days and tastes even better the next day.","The notebook's version with dried tomatoes works too, reduce the roasting time to about 45 minutes if using them."],"id":"70898d41-065c-41b4-b33d-d51c5d11e9e4"},{"notes":["Halloumi must be proper Cyprus halloumi, soft halloumi will melt and won't squeak. Find it at the deli counter or with the international cheeses.","Eat it straight from the pan while it's still hot and squeaky. Once it cools, it toughens up.","This works as an appetiser before a big feed, or as a quick snack with cold beer on a Saturday arvo."],"steps":[{"text":"Heat a shallow pan over medium-high heat. Pour in enough oil so it's about 5 mm deep, then get it really hot, it should shimmer and just start to smoke."},{"text":"Dust the halloumi slices lightly in flour on both sides, shaking off any excess."},{"text":"When the oil's smoking, carefully lay the halloumi slices into the pan. You should hear them sizzle immediately. Don't move them."},{"text":"Cook for about 2 minutes until the underside is deep golden. Flip and cook the other side for another 2 minutes until it's the same colour. It should squeak when you bite into it."},{"text":"Transfer to a plate, season with salt, and serve straight away with lemon wedges on the side. Squeeze lemon over each piece and eat it hot."}],"id":"33f8f5b5-a4cf-4d86-af56-345acdcfa396"},{"notes":["Make ahead: Shape the kebabs up to 4 hours ahead, cover and refrigerate until ready to fry.","For extra flavour, add 1 tbsp of tamarind paste to the mixture before shaping.","These freeze well raw: freeze shaped kebabs on a tray, then transfer to a container. Fry from frozen, allowing an extra 2 to 3 minutes per side.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C. Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"49d73230-5dea-4ca7-a6d9-046ca6e2fe9e"},{"notes":["The oysters must be eaten as soon as they come out of the oven, while the butter is still foaming.","If shucking oysters yourself, chill them in the freezer for 15 minutes first, they open more easily.","You can make the herb butter a few hours ahead and chill it, then scoop it on to the oysters just before baking."],"id":"bb4730fc-0ea4-4d10-9993-e32ba4b2dcae"},{"notes":["Press the tofu overnight or for at least 2 hours before cooking so it fries crispy and stays that way. You can make the filling components ahead and assemble the rolls right before serving.","Swap the herbs for whatever's fresh, Thai basil works beautifully, or try rocket for something peppery."],"id":"5bac0e7a-09ef-49cc-bcde-00c19249e522"},{"notes":["Don't overcrowd the pan, if you're cooking for more than 4, cook in two batches so the squid fries rather than steams.","Squid cooks fast: longer than 3–4 minutes and it toughens. In and out.","Serve with crusty bread to mop up the pan juices.","Food safety: Cook squid and octopus until opaque and firm, and keep seafood chilled until you cook it."],"steps":[{"text":"Score the squid tubes in a fine crosshatch, cutting about halfway through the flesh. Pat dry with paper towel and cut into bite-sized pieces (about 4 cm square)."},{"text":"Place a large frying pan or wok over high heat until it's smoking hot, about 2 minutes."},{"text":"Add the olive oil, then immediately add the squid pieces, chilli and garlic. Stir constantly for about 2 minutes, the squid will curl and become opaque."},{"text":"Season with salt and pepper to taste, then squeeze lemon juice over and toss through."},{"text":"Serve immediately, scattered with fresh parsley if you like, with extra lemon wedges on the side."}],"id":"74052578-daeb-4943-99c2-414945f3af42"},{"diets":[],"notes":["Make the pasta and filling up to 2 hours ahead; keep the cut agnolotti on a tray in the fridge, uncovered, until you cook them.","If your filling is too wet, the agnolotti will split. If the ricotta is very creamy, drain it in a sieve lined with kitchen paper for 10 minutes first.","For a vegetarian version, use a vegetarian hard cheese (made without animal rennet)."],"steps":[{"text":"Make the pasta dough: tip flour into a mound on a work surface, make a well in the centre, crack in eggs, add oil and a pinch of salt. Work with a fork until shaggy, then knead for 8 minutes until smooth. Wrap and rest 20 minutes."},{"text":"While the dough rests, make the filling: mix ricotta, spinach, parmesan, egg yolk and garlic. Season generously with salt, pepper and nutmeg, taste it, it should be well-seasoned."},{"text":"Dust your work surface. Roll the dough to the thickness of a coin (about 1 mm). Using a 7 cm round cutter, stamp out circles."},{"text":"Place a small spoonful of filling (about ½ tsp) on one half of each circle. Fold in half, press the edges to seal, then fold the corners up and press them together to make a purse shape. Place on a floured tray as you go."},{"text":"Bring a large pot of salted water to a boil. Melt the butter in a separate pan over medium heat until it turns golden and smells nutty, 5 minutes. Add the sage leaves."},{"text":"Drop the agnolotti into the boiling water. They'll sink, then bob to the surface after 2–3 minutes. Cook for another 2 minutes, then remove with a slotted spoon and add to the brown butter. Toss gently."},{"text":"Divide among bowls. Add a pinch of salt and grate parmesan over the top."}],"id":"97270ac2-cdc8-4191-b895-dd7b9fd843c4"},{"notes":["Use fresh egg noodles from the fridge section if you can, they won't clump. No fresh? Cooked noodles work fine; just break them up as you add them.","The paste can be made 30 minutes ahead and kept in a bowl.","Push for medium heat, you want the paste to fry properly but the noodles not to burn on the bottom.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"id":"8ef2ad89-ef4c-4d1f-b409-bdb5719cc1df"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;